using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class Req2129GeneratedFormatterRequirementTests
{
    private static readonly CSharpParseOptions ParseOptions = new(LanguageVersion.CSharp12);

    private static async Task<ImmutableArray<MetadataReference>> GetFrameworkReferencesAsync()
        => await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);

    private static MetadataReference CompileProjectA(string source, IEnumerable<MetadataReference> references)
    {
        CSharpCompilation compilation = CSharpCompilation.Create(
            "ProjectA",
            new[] { CSharpSyntaxTree.ParseText(source, ParseOptions) },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        using MemoryStream stream = new();
        var result = compilation.Emit(stream);
        Assert.True(result.Success, string.Join(Environment.NewLine, result.Diagnostics));
        return MetadataReference.CreateFromImage(stream.ToArray());
    }

    private static (string GeneratedText, Compilation Output, ImmutableArray<Diagnostic> GeneratorDiagnostics) RunGenerator(string source, IEnumerable<MetadataReference> references)
    {
        CSharpCompilation compilation = CSharpCompilation.Create(
            "ProjectB",
            new[] { CSharpSyntaxTree.ParseText(source, ParseOptions) },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            new[] { new global::MessagePack.SourceGenerator.MessagePackGenerator().AsSourceGenerator() },
            parseOptions: ParseOptions);
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation output, out ImmutableArray<Diagnostic> diagnostics);
        GeneratorDriverRunResult runResult = driver.GetRunResult();
        string text = string.Join("\n", runResult.GeneratedTrees.Select(t => t.ToString()));
        return (text, output, diagnostics);
    }

    private static void AssertNoErrors(Compilation output, ImmutableArray<Diagnostic> generatorDiagnostics)
    {
        Assert.Empty(generatorDiagnostics.Where(d => d.Severity == DiagnosticSeverity.Error));
        var errors = output.GetDiagnostics().Where(d => d.Severity == DiagnosticSeverity.Error).ToList();
        Assert.True(errors.Count == 0, string.Join(Environment.NewLine, errors));
    }

    [Fact]
    public async Task GeneratesBodylessFormatterForReferencedAssemblyType()
    {
        ImmutableArray<MetadataReference> framework = await GetFrameworkReferencesAsync();
        string projectA = """
            namespace ProjectA
            {
                public class MyType
                {
                    public int Id { get; set; }
                    public string Name { get; set; }
                }
            }
            """;
        MetadataReference projectARef = CompileProjectA(projectA, framework);

        string projectB = """
            using MessagePack;
            using MessagePack.Formatters;

            namespace ProjectB
            {
                [GeneratedMessagePackResolver]
                partial class MyResolver { }

                [GeneratedMessagePackFormatter]
                partial class MyTypeFormatter : IMessagePackFormatter<ProjectA.MyType>;
            }
            """;
        var references = framework.Concat(ReferencesHelper.GetReferences(ReferencesSet.MessagePack)).Append(projectARef).ToList();
        var (text, output, diagnostics) = RunGenerator(projectB, references);

        AssertNoErrors(output, diagnostics);
        Assert.Contains("partial class MyTypeFormatter", text);
        Assert.Contains("Name", text);
    }

    [Fact]
    public async Task HonoursMessagePackAttributesOnReferencedType()
    {
        ImmutableArray<MetadataReference> framework = await GetFrameworkReferencesAsync();
        var messagePackRefs = ReferencesHelper.GetReferences(ReferencesSet.MessagePack).ToList();
        string projectA = """
            using MessagePack;

            namespace ProjectA
            {
                [MessagePackObject]
                public class KeyedType
                {
                    [Key(0)]
                    public int Id { get; set; }

                    [Key(1)]
                    public string Label { get; set; }

                    [IgnoreMember]
                    public string IgnoredSecretValue { get; set; }
                }
            }
            """;
        MetadataReference projectARef = CompileProjectA(projectA, framework.Concat(messagePackRefs));

        string projectB = """
            using MessagePack;
            using MessagePack.Formatters;

            namespace ProjectB
            {
                [GeneratedMessagePackResolver]
                partial class MyResolver { }

                [GeneratedMessagePackFormatter]
                partial class KeyedTypeFormatter : IMessagePackFormatter<ProjectA.KeyedType>;
            }
            """;
        var references = framework.Concat(messagePackRefs).Append(projectARef).ToList();
        var (text, output, diagnostics) = RunGenerator(projectB, references);

        AssertNoErrors(output, diagnostics);
        Assert.Contains("partial class KeyedTypeFormatter", text);
        Assert.DoesNotContain("IgnoredSecretValue", text);
        Assert.Contains("WriteArrayHeader", text);
    }
}
